(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+wx1, sy = y+wy1;
  const wx2 = Math.sin(sx*0.025+t*0.15)*8+Math.cos(sy*0.03-t*0.4)*6;
  const wy2 = Math.cos(sx*0.02-t*0.3)*8+Math.sin(sy*0.022+t*0.45)*6;
  const dx = sx+wx2, dy = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*50,0.14,2.1,0.85],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*40,0.11,1.8,1.05]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    const w1=Math.sin(d*f-t*sp),w2=Math.cos(d*f*0.7+t*sp*0.6+1.5);
    aS+=w1*w; iS+=w2*w; cS+=w1*w2*w;
  }
  const n=src.reduce((a,s)=>a+s[4],0);
  const act=aS/n,inh=iS/n,cross=cS/n;
  const bg=(Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2+Math.sin((dx+dy)*0.12+t*2.5)*0.2+Math.sin((dx-dy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2),ang=Math.atan2(dy-cy,dx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.03+ang*6-t*0.8)+Math.cos(dist*0.07-ang*2+t*1.0))*0.2;
  const fine=(Math.sin(dx*0.3+t*3)*Math.sin(dy*0.35-t*2.5)+Math.sin(dx*0.2-dy*0.25+t*4)*0.5)*0.15;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((cross+spiral2+fine)*2.5);
  const cell=Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=r1*0.55+r2*0.2+cell*0.25;
  const v=blend*0.5+0.5;
  const pal=[[5,10,45],[12,45,90],[18,95,125],[30,155,145],[120,185,100],[200,190,60],[220,140,55],[195,85,65],[150,45,75],[90,25,60],[40,15,50],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(blend*Math.PI)*0.2;
  const edge=Math.abs(blend)>0.7?1.15:1.0;
  const glow=Math.max(0,Math.abs(blend)-0.5)*0.3;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*20)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*60)|0
  ];
}
